// Simulating a Traffic Light System in JavaScript

// Traffic light states
const trafficLightStates = [
  { color: "Red", duration: 5000 },    // Red light stays for 5 seconds
  { color: "Green", duration: 4000 }, // Green light stays for 4 seconds
  { color: "Yellow", duration: 2000 } // Yellow light stays for 2 seconds
];

// Function to simulate the traffic light system
function simulateTrafficLight() {
  let currentIndex = 0;

  // Function to update the traffic light state
  const updateLight = () => {
    const state = trafficLightStates[currentIndex];
    console.log(`Traffic Light: ${state.color}`); // Log the current light color

    // Move to the next state after the current state's duration
    setTimeout(() => {
      currentIndex = (currentIndex + 1) % trafficLightStates.length; // Cycle back to the beginning
      updateLight(); // Call the function recursively to continue the cycle
    }, state.duration);
  };

  updateLight(); // Start the cycle
}

// Run the simulation
simulateTrafficLight();
```

