async function displayData() {
  try {
    const endpoint = '/search?q=artist:Coldplay&type=artist'; // Example: Search for artist "Coldplay"
    const data = await fetchSpotifyData(endpoint);
    console.log('Spotify Data:', data); // Display data in the console or customize display logic
